  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.15);
}

.question-title {
  font-size: 1.1em;
  font-weight: 600;
  padding: 1.2em 1.5em;
  border-bottom: 1px solid rgba(0, 0, 0, 0.1);
}

