  margin-top: 0.5em;
}

.number-input-wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5em;
}

.unit-toggle-container {
  display: flex;
  justify-content: center;
}

.unit-toggle {
  display: flex;
  gap: 0.5em;
  justify-content: center;
}

.unit-btn {
  padding: 0.5em 1.5em;
