<template>
  <LoadingElement v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        firstElement="Bonjour"
        :secondElement="authStore.userInfos?.username"
        coloredSecond="true"
      ></TopDeck>
      <div class="noSpaceRowAction">
        <ThemeToggle />
        <AccountToggle displayLogout="true" />
      </div>
    </div>
    <div class="myBasicInfosContainer">
      <div class="basicInfosHeader">
        <div class="basicInfosTitle">
          <v-icon size="20">mdi-account-circle</v-icon>
          <h2>Mes informations de base</h2>
        </div>
        <v-btn
          color="accent"
          variant="outlined"
          class="basicInfosButton"
          rounded="xl"
          size="small"
          @click="changePassword"
        >
          <v-icon icon="mdi-pencil" class="mr-2"></v-icon>
          Changer mon mot de passe
        </v-btn>
      </div>
      <div class="basicInfosBody">
        <div class="basicInfosRow">
          <span class="basicInfosLabel">Nom</span>
          <span class="basicInfosValue">{{ authStore.userInfos?.username || "—" }}</span>
        </div>
        <div class="basicInfosRow">
          <span class="basicInfosLabel">Email</span>
          <span class="basicInfosValue">{{ authStore.userInfos?.email || "—" }}</span>
        </div>
      </div>
    </div>
    <HealthStatsBloc />
    <Info_display_bloc :user="authStore.userInfos" />
  </div>

  <v-snackbar
    v-model="showSnack"
    :color="snackColor"
    :timeout="2000"
    location="bottom"
  >
    {{ snackMessage }}
  </v-snackbar>

  <!-- 🔹 Modal de changement de mot de passe -->
  <v-dialog v-model="showPasswordDialog" max-width="420">
    <v-card class="passwordModal">
      <v-card-title class="passwordModal__header">
        <div class="passwordModal__title">
          <v-icon class="passwordModal__icon">mdi-lock-reset</v-icon>
          <span>Changer mon mot de passe</span>
        </div>
        <v-btn icon variant="text" class="passwordModal__close" @click="showPasswordDialog = false">
          <v-icon>mdi-close</v-icon>
        </v-btn>
      </v-card-title>
      <v-divider />
      <v-card-text class="passwordModal__body">
        <form @submit.prevent="onSubmit" class="passwordModal__form">
          <v-text-field
            v-model="email"
            type="email"
            label="Votre e-mail"
            variant="outlined"
            density="compact"
            required
            prepend-inner-icon="mdi-email-outline"
          />
          <v-btn
            :loading="loading"
            type="submit"
            color="accent"
            rounded="xl"
            class="passwordModal__submit"
          >
            <v-icon icon="mdi-email-fast-outline" class="mr-2" />
            {{ loading ? "Envoi…" : "Envoyer le lien" }}
          </v-btn>
          <p v-if="done" class="passwordModal__hint">
            Si un compte existe pour cet e-mail, un message vient d’être envoyé.
          </p>
          <p v-if="error" class="passwordModal__error">{{ error }}</p>
        </form>
      </v-card-text>
      <v-card-actions class="passwordModal__actions">
        <v-spacer />
        <v-btn variant="text" class="passwordModal__ghost" @click="showPasswordDialog = false">
          Fermer
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { ref } from "vue";
import { getAuth, signOut } from "firebase/auth";
import { useRouter } from "vue-router";
import TopDeck from "../Utils/TopDeck.vue";
import LoadingElement from "../Animations/LoadingElement.vue";
import { useAuthStore } from "@/store/auth_store";
import Info_display_bloc from "./InfoDisplayBlock.vue";
import { requestPasswordReset } from "@/service/auth_service";
import HealthStatsBloc from "./HealthStatsBloc.vue";
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";

export default {
  name: "ProfilPage",
  components: {
    LoadingElement,
    TopDeck,
    Info_display_bloc,
    HealthStatsBloc,
    ThemeToggle,
    AccountToggle,
  },
  setup() {
    const router = useRouter();
    const auth = getAuth();
    const authStore = useAuthStore();
    // Thème géré par ThemeToggle
    const showSnack = ref(false);
    const snackMessage = ref("");
    const snackColor = ref("success");

    const showPasswordDialog = ref(false);
    const email = ref("");
    const loading = ref(false);
    const done = ref(false);
    const error = ref("");

    const changePassword = () => {
      showPasswordDialog.value = true;
    };

    async function onSubmit() {
      loading.value = true;
      error.value = "";
      try {
        await requestPasswordReset(email.value);
        done.value = true; // message générique
      } catch (e) {
        console.error("requestPasswordReset error", e);
        done.value = true;
      } finally {
        loading.value = false;
      }
    }

    const handleSignout = () => {
      signOut(auth)
        .then(() => {
          router.push("/login");
        })
        .catch((error) => {
          console.error(error);
        });
    };

    return {
      authStore,
      showSnack,
      snackMessage,
      snackColor,
      showPasswordDialog,
      email,
      loading,
      done,
      error,
      onSubmit,
      handleSignout,
      changePassword,
    };
  },
};
</script>

