<template>
  <v-card
    class="recipe-card bg-tertiary"
    elevation="0"
    max-width="380"
  >
    <div class="recipe-media">
      <v-img
        class="recipe-img"
        height="190px"
        :src="previewSrc"
        cover
        @error="onPreviewError"
      >
        <template #placeholder>
          <v-row
            class="fill-height ma-0"
            align="center"
            justify="center"
          >
            <v-progress-circular indeterminate color="white"></v-progress-circular>
          </v-row>
        </template>
      </v-img>
      <div class="recipe-media__overlay"></div>
      <v-chip
        size="small"
        class="recipe-chip"
        variant="elevated"
        color="surface"
      >
        {{ $t(item.category) }}
      </v-chip>
      <v-btn
        class="recipe-fav"
        icon
        variant="text"
        :color="item.favorite ? 'warning' : ''"
        @click.stop="toggleFavorite"
      >
        <v-icon>
          {{ item.favorite ? "mdi-star" : "mdi-star-outline" }}
        </v-icon>
      </v-btn>
    </div>

    <div class="recipe-body">
      <h3 class="recipe-title line-clamp-1">
        {{ item.title || "Sans titre" }}
      </h3>

      <div class="recipe-meta" v-if="item.totals?.kcal || item.servings">
        <span class="recipe-meta__pill" v-if="item.totals?.kcal">
          {{ Math.round(item.totals.kcal) }} kcal
        </span>
        <span class="recipe-meta__pill" v-if="item.servings">
          {{ item.servings }} portions
        </span>
      </div>

      <div class="recipe-actions">
        <v-btn class="recipe-btn" color="accent" variant="tonal" @click="openDetails">
          Voir
        </v-btn>

        <v-spacer></v-spacer>
        <v-btn
          class="recipe-toggle"
          :icon="show ? 'mdi-chevron-up' : 'mdi-chevron-down'"
          variant="text"
          @click="show = !show"
        ></v-btn>
      </div>
    </div>

    <!-- CONTENU DÉPLIABLE -->
    <v-expand-transition>
      <div v-show="show">
        <v-divider class="recipe-divider"></v-divider>

        <v-card-text class="recipe-details text-body-2 mt-2">
          <div>
            <strong>Totaux :</strong>
            {{ item.totals?.grams ?? 0 }} g —
            {{ item.totals?.kcal ?? 0 }} kcal
            <br />
            P {{ formatValue(item.totals?.protein) }} g •
            G {{ formatValue(item.totals?.carbs) }} g •
            L {{ formatValue(item.totals?.fat) }} g
          </div>

          <div
            v-if="item.servings && item.servings > 0"
            class="text-caption mt-1"
          >
            <strong>Par portion ({{ item.servings }}) :</strong>
            {{ Math.round((item.totals?.kcal ?? 0) / item.servings) }} kcal
          </div>

          <div class="recipe-delete">
            <v-btn
              class="recipe-btn"
              color="accent"
              variant="tonal"
              @click="createShoppingList"
            >
              <v-icon start size="18">mdi-cart-plus</v-icon>
              Créer liste
            </v-btn>
            <v-btn
              class="recipe-btn recipe-btn--danger"
              color="error"
              variant="text"
              @click="deleteRecipe"
            >
              Supprimer la recette
            </v-btn>
          </div>
        </v-card-text>
      </div>
    </v-expand-transition>
    <v-snackbar v-model="snack.show" :timeout="2500">
      {{ snack.text }}
    </v-snackbar>
  </v-card>
</template>

<script setup>
import { ref, computed, watch } from "vue";
import { useRouter } from "vue-router";
import { useAuthStore } from "@/store/auth_store";
import { addShoppingList, getUserShoppingLists } from "@/service/shopping_list_service";
import { getIngredientsByBarcodes } from "@/service/ingredient_service";
import { getUserRecipeById } from "@/service/recipe_service";
import { getBaseRecipeById } from "@/service/base_recipe_service";
import { defineProps, defineEmits } from "vue";

const props = defineProps({
  item: {
    type: Object,
    required: true,
  },
});

const emit = defineEmits(["toggle-favorite", "delete"]);
const router = useRouter();
const authStore = useAuthStore();
const show = ref(false);
const snack = ref({ show: false, text: "" });
// Preview fallback logic: prefer item.url, then item.image, then item.imageUrl.
const validPreview = ref(true);
const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg'

const sourceKey = computed(() => {
  return props.item?.url || props.item?.image || props.item?.imageUrl || '';
});

const previewSrc = computed(() => {
  return validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage;
});

function onPreviewError() {
  validPreview.value = false;
}

// reset validity when the source changes
watch(sourceKey, (v) => {
  validPreview.value = !!v;
});

function toggleFavorite() {
  emit("toggle-favorite", props.item);
}

function openDetails() {
  router.push({
    name: "recipe_detail",
    params: { id: props.item.id },
  });
}

function deleteRecipe() {
  emit("delete", props.item.id);
}

async function createShoppingList() {
  if (!authStore.userid) {
    snack.value = { show: true, text: "Utilisateur non connecté." };
    return;
  }

  try {
    let r = await getUserRecipeById(authStore.userid, props.item.id);
    if (!r || r.baseRecipe === true) {
      const base = await getBaseRecipeById(props.item.id);
      if (base) {
        r = base;
      }
    }

    const ingredients = r?.ingredients || [];
    if (!ingredients.length) {
      snack.value = { show: true, text: "Aucun ingrédient à ajouter." };
      return;
    }

    const barcodes = ingredients.map((ing) => ing?.id).filter(Boolean);
    const fullInfos = barcodes.length
      ? await getIngredientsByBarcodes(authStore.userid, barcodes)
      : [];

    const items = ingredients
      .map((ing) => {
        const found = fullInfos.find((f) => f.id === ing?.id);
        const name = String(
          ing?.name || found?.productName || ing?.productName || ing?.id || ""
        ).trim();
        if (!name) return null;
        const grams = Number(ing.grams);
        const quantity = Number.isFinite(grams) && grams > 0 ? `${grams} g` : 1;
        return { name, quantity };
      })
      .filter(Boolean);

    if (!items.length) {
      snack.value = { show: true, text: "Aucun ingrédient valide." };
      return;
    }

    const listName = String(r?.title || props.item.title || "Liste de courses").trim();
    const existingLists = await getUserShoppingLists(authStore.userid);
    const alreadyGenerated = Object.values(existingLists || {}).some((list) => {
      if (!list) return false;
      const sameName = String(list.name || "").trim().toLowerCase() === listName.toLowerCase();
      return sameName && list.userGenerated === false;
    });
    if (alreadyGenerated) {
      snack.value = { show: true, text: "Cette liste existe déjà." };
      return;
    }

    await addShoppingList(authStore.userid, { name: listName, items, userGenerated: false });
    snack.value = { show: true, text: "Liste de courses créée." };
  } catch (e) {
    console.error(e);
    snack.value = { show: true, text: "Erreur lors de la création de la liste." };
  }
}

function formatValue(value) {
  return value?.toFixed ? value.toFixed(1) : value ?? 0;
}
</script>

