<template>
  <v-navigation-drawer app expand-on-hover rail color="primary">
    <v-list>
      <v-list-item
        @click="() => $router.push('/')"
        title="Saineo"
      >
        <template #prepend>
          <v-avatar size="32">
            <v-img :src="logoSrc" alt="Logo Saineo" />
          </v-avatar>
        </template>
      </v-list-item>
      <!-- :subtitle=authStore.userInfos?.email -->
    </v-list>
    <v-list density="compact" nav>
      <v-list-item
        v-for="(menu, index) in menus"
        :key="index"
        :to="menu.link"
        :prepend-icon="menu.prependIcon"
        :class="{ 'active-menu': $route.path === menu.link }"
      >
        <v-list-item-title>{{ menu.title }}</v-list-item-title>
      </v-list-item>
    </v-list>
  </v-navigation-drawer>
</template>

<script>
import { useAuthStore } from "@/store/auth_store";
import { getAuth } from "firebase/auth";
import { ref, computed } from "vue";
import { useTheme } from "vuetify";
import logoUrl from "@/assets/logo.png";
import lightLogoUrl from "@/../assets/lightLogo.png";

export default {
  name: "NavBarUser",
  setup() {
    const theme = useTheme();
    const authStore = useAuthStore();
    const menus = ref([
      {
        title: "Recettes",
        link: "/my_recipes",
        prependIcon: "mdi-book-outline",
      },
      {
        title: "Ingredients",
        link: "/my_ingredients",
        prependIcon: "mdi-food-apple-outline",
      },
      {
        title: "Menus",
        link: "/menu",
        prependIcon: "mdi-clipboard-list-outline",
      },
      { title: "Courses", link: "/shopping_list", prependIcon: "mdi-cart" },
    ]);

    const logout = () => {
      const auth = getAuth();
      auth
        .signOut()
        .then(() => (window.location.href = "#/login"))
        .catch((error) => console.error("Error signing out: ", error));
    };

    const logoSrc = computed(() =>
      theme.global.name.value === "dark" ? lightLogoUrl : logoUrl
    );

    return {
      authStore,
      menus,
      logout,
      logoSrc,
    };
  },
};
</script>

<style scoped>
.active-menu {
  color: green;
}

.active-menu .v-icon {
  color: green !important;
}
</style>
