<template>
    <div class="py-6 px-4 bg-primary main">
        <div class="rowSpaceBetween fullWidth mb-6">
          <TopDeck
            firstElement="Détail"
            secondElement="recette"
            :coloredSecond="true"
            actionHeaderIcon="mdi-arrow-left"
            :actionheaderFunction="() => $router.back()"
            actionHeaderColor="accent"
            actionHeaderTextColor="white"
          />
          <div class="rowCustom">
            <ThemeToggle />
            <AccountToggle />
          </div>
        </div>

        <v-card class="recipe-detail-card pa-6 rounded-xl" elevation="2" color="secondary">
          <div class="recipe-hero">
            <v-img
              class="recipe-hero__img"
              height="240"
              :src="previewSrc"
              cover
              @error="onPreviewError"
            >
              <template #placeholder>
                <v-row
                  class="fill-height ma-0"
                  align="center"
                  justify="center"
                >
                  <v-progress-circular indeterminate color="white"></v-progress-circular>
                </v-row>
              </template>
            </v-img>
          </div>
          <!-- Header avec titre et catégorie -->
          <div class="recipe-header mb-4">
            <div class="recipe-header__left">
              <h1 class="text-h4 font-weight-bold recipe-title">
                {{ recipe?.title || 'Sans titre' }}
              </h1>
              <v-btn
                class="recipe-generate-btn"
                color="accent"
                variant="flat"
                @click="createShoppingListFromRecipe()"
              >
                <v-icon start>mdi-cart-plus</v-icon>
                Liste de courses
              </v-btn>
            </div>
            <div class="recipe-header__actions">
              <v-chip
                v-if="recipe?.category"
                class="recipe-category-chip"
                variant="tonal"
                size="default"
                prepend-icon="mdi-tag"
              >
                {{ $t(recipe.category) }}
              </v-chip>

              <v-btn
                v-if="canEditBaseRecipe"
                class="recipe-action-btn"
                color="secondary"
                icon
                size="small"
                variant="tonal"
                @click="editRecipe()"
              >
                <v-icon size="18">mdi-pencil</v-icon>
              </v-btn>

              <v-btn
                v-if="!recipe?.baseRecipe && !isFromBaseCatalog"
                class="recipe-action-btn"
                :color="recipe?.favorite ? 'warning' : 'grey'"
                icon
                size="small"
                variant="tonal"
                @click="toggleFavorite()"
              >
                <v-icon size="18">
                  {{ recipe?.favorite ? 'mdi-star' : 'mdi-star-outline' }}
                </v-icon>
              </v-btn>

              <v-btn
                v-if="canEditBaseRecipe"
                class="recipe-action-btn"
                color="error"
                icon
                size="small"
                variant="tonal"
                @click="requestDelete"
              >
                <v-icon size="18">mdi-delete</v-icon>
              </v-btn>
            </div>
          </div>

          <!-- Notes avec icône -->
          <div v-if="recipe?.notes" class="recipe-notes-wrapper mb-5">
            <div class="d-flex align-center mb-2">
              <v-icon size="small" class="mr-2 detail-icon">mdi-note-text</v-icon>
              <span class="text-subtitle-2 font-weight-medium detail-text">Notes</span>
            </div>
            <div class="recipe-notes text-body-2 ml-7 detail-text" v-html="recipe.notes"></div>
          </div>

          <!-- Nova warning -->
          <v-alert
            v-if="novaWarning"
            :type="novaWarning.type"
            variant="tonal"
            class="mb-5"
            :icon="novaWarning.icon"
            prominent
            border="start"
          >
            {{ novaWarning.message }}
          </v-alert>

          <div class="recipe-split">
            <!-- Nutrition totals -->
            <div class="recipe-split__col recipe-split__col--nutrition">
              <div class="d-flex align-center mb-4">
                <v-icon class="mr-2 detail-icon">mdi-nutrition</v-icon>
                <h2 class="text-h6 font-weight-bold detail-text">Valeurs nutritionnelles</h2>
              </div>
              <v-card class="nutrition-card pa-4 rounded-lg" color="tertiary" elevation="0">
                <div class="text-body-1 mb-2 detail-text">
                  <v-icon size="small" class="mr-1 detail-icon">mdi-weight</v-icon>
                  <strong>{{ recipe?.totals?.grams ?? 0 }} g</strong> — 
                  <v-icon size="small" class="mx-1 detail-icon">mdi-fire</v-icon>
                  <strong>{{ recipe?.totals?.kcal ?? 0 }} kcal</strong>
                </div>
                <v-divider class="my-2"></v-divider>
                <div class="text-body-2 detail-text">
                  <div class="d-flex justify-space-between mb-1">
                    <span>Protéines</span>
                    <strong>{{ format1(recipe?.totals?.protein) }} g</strong>
                  </div>
                  <div class="d-flex justify-space-between mb-1">
                    <span>Glucides</span>
                    <strong>{{ format1(recipe?.totals?.carbs) }} g</strong>
                  </div>
                  <div class="d-flex justify-space-between">
                    <span>Lipides</span>
                    <strong>{{ format1(recipe?.totals?.fat) }} g</strong>
                  </div>
                </div>
                <v-divider class="my-3" v-if="recipe?.servings && recipe.servings > 0"></v-divider>
                <div class="text-body-2 d-flex align-center detail-text" v-if="recipe?.servings && recipe.servings > 0">
                  <v-icon size="small" color="accent" class="mr-2">mdi-account-multiple</v-icon>
                  <span><strong>Par portion ({{ recipe.servings }}):</strong> {{ Math.round((recipe?.totals?.kcal ?? 0) / recipe.servings) }} kcal</span>
                </div>
              </v-card>
            </div>

            <!-- Ingredients section -->
            <div class="recipe-split__col recipe-split__col--ingredients">
              <div class="d-flex align-center mb-4">
                <v-icon class="mr-2 detail-icon">mdi-food-apple</v-icon>
                <h2 class="text-h6 font-weight-bold detail-text">Ingrédients</h2>
              </div>
              
              <v-alert v-if="!recipe?.ingredients?.length" type="info" variant="tonal" icon="mdi-information">
                  Aucune ligne d’ingrédient.
              </v-alert>
              <v-list v-else density="compact" class="listTile ingredients-list rounded-lg">
                  <template v-for="(ing, i) in recipe.ingredients" :key="i">
                    <v-list-item class="ingredient-item px-4 py-3">
                      <template v-slot:prepend>
                        <v-avatar size="40" class="mr-3 ingredient-avatar">
                          <v-icon size="22" class="ingredient-icon">mdi-food-variant</v-icon>
                        </v-avatar>
                      </template>
                      
                      <div class="flex-grow-1">
                        <v-list-item-title class="font-weight-bold mb-2">
                          {{ ing.name || ing.productName }}
                        </v-list-item-title>
                        <div class="d-flex align-center gap-2">
                          <v-tooltip v-if="getNovaDisplay(ing.novaGroup)" :text="$t(getNovaDisplay(ing.novaGroup).string)">
                            <template v-slot:activator="{ props }">
                              <v-chip
                                :color="getNovaDisplay(ing.novaGroup).color"
                                size="x-small"
                                variant="flat"
                                class="text-white font-weight-bold"
                                v-bind="props"
                                label
                              >
                                Nova {{ getNovaNumber(ing.novaGroup) }}
                              </v-chip>
                            </template>
                          </v-tooltip>
                        </div>
                      </div>
                      
                      <template v-slot:append>
                        <v-chip
                          color="accent"
                          variant="elevated"
                          size="small"
                          label
                          class="font-weight-bold"
                        >
                          <v-icon start size="16">mdi-weight-gram</v-icon>
                          {{ ing.grams }}g
                        </v-chip>
                      </template>
                    </v-list-item>
                    <v-divider v-if="i < recipe.ingredients.length - 1" class="my-0"></v-divider>
                  </template>
              </v-list>
            </div>
          </div>
        </v-card>


        <!-- Dialog confirmation suppression -->
        <v-dialog v-model="askDelete" max-width="420">
            <v-card>
                <v-card-title>Supprimer la recette ?</v-card-title>
                <v-card-text>
                Cette action est définitive.
                </v-card-text>
                <v-card-actions>
                <v-spacer/>
                <v-btn variant="text" @click="askDelete=false">Annuler</v-btn>
                <v-btn color="error" @click="deleteRecipe">Supprimer</v-btn>
                </v-card-actions>
            </v-card>
        </v-dialog>

        <v-snackbar v-model="snack.show" :timeout="2500">{{ snack.text }}</v-snackbar>
        <v-alert v-if="errorMessage" type="error" variant="tonal" class="mt-4">
            {{ errorMessage }}
        </v-alert>
    </div>
</template>

<script setup>
  import { ref, computed, onMounted, watch, defineProps } from 'vue'
  import { useRouter, useRoute } from 'vue-router'
  import { useAuthStore } from '@/store/auth_store'
  import { getUserRecipeById, deleteRecipeFromUserCollection, setRecipeAsFavorite } from '@/service/recipe_service'
  import { getBaseRecipeById, deleteBaseRecipe } from '@/service/base_recipe_service'
  import { getIngredientsByBarcodes, getNovaStringAndColor } from '@/service/ingredient_service'
  import { addShoppingList, getUserShoppingLists } from '@/service/shopping_list_service'
  import TopDeck from '@/components/Utils/TopDeck.vue'

  const props = defineProps({ id: { type: String, required: true } })

  const router = useRouter()
  const route = useRoute()
  const authStore = useAuthStore()

  const recipe = ref(null)
  const isLoading = ref(false)
  const errorMessage = ref('')
  const snack = ref({ show: false, text: '' })

  const askDelete = ref(false)
  const isAdmin = computed(() => authStore.userInfos?.role === 'admin')
  const isFromBaseCatalog = computed(() => route.query?.source === 'base')
  const canEditBaseRecipe = computed(() => {
    if (!recipe.value) return false
    if (isFromBaseCatalog.value) return isAdmin.value
    return !recipe.value.baseRecipe || isAdmin.value
  })
  const validPreview = ref(true)
  const placeholderImage = 'https://www.mimisrecipes.com/wp-content/uploads/2018/12/recipe-placeholder-featured.jpg'

  const sourceKey = computed(() => {
    return recipe.value?.url || recipe.value?.image || recipe.value?.imageUrl || ''
  })

  const previewSrc = computed(() => {
    return validPreview.value && sourceKey.value ? sourceKey.value : placeholderImage
  })

  function onPreviewError() {
    validPreview.value = false
  }

  const novaWarning = computed(() => {
    if (!recipe.value?.ingredients?.length) return null
    
    const novaGroups = recipe.value.ingredients
      .map(ing => {
        const display = getNovaDisplay(ing.novaGroup)
        if (!display) return null
        const match = display.string.match(/\d+/)
        return match ? parseInt(match[0]) : null
      })
      .filter(n => n !== null)
    
    if (!novaGroups.length) return null
    
    // Count nova 3 and 4 (ultra-processed)
    const hasNova4 = novaGroups.some(n => n === 4)
    const hasNova3 = novaGroups.some(n => n === 3)
    const nova4Count = novaGroups.filter(n => n === 4).length
    const nova3Count = novaGroups.filter(n => n === 3).length
    
    if (hasNova4) {
      return {
        type: 'error',
        icon: 'mdi-alert-circle',
        message: `Cette recette contient ${nova4Count} ingrédient(s) ultra-transformé(s) (Nova 4). Consommation à limiter.`
      }
    }
    
    if (hasNova3 && nova3Count > 1) {
      return {
        type: 'warning',
        icon: 'mdi-alert',
        message: `Cette recette contient ${nova3Count} ingrédients transformés (Nova 3). À consommer avec modération.`
      }
    }
    
    return null
  })

  function getNovaDisplay(novaGroup) {
    if (!novaGroup) return null
    
    let num = null
    
    // Handle different formats: number, object with string property, or direct object
    if (typeof novaGroup === 'number') {
      num = novaGroup
    } else if (typeof novaGroup === 'object') {
      if (novaGroup.string) {
        // Extract number from "nova.X" format
        const match = novaGroup.string.match(/\d+/)
        num = match ? parseInt(match[0]) : null
      } else if (typeof novaGroup.value === 'number') {
        num = novaGroup.value
      }
    } else if (typeof novaGroup === 'string') {
      // Extract from "nova.X" or just "X"
      const match = novaGroup.match(/\d+/)
      num = match ? parseInt(match[0]) : null
    }
    
    if (!num || num < 1 || num > 4) return null
    return getNovaStringAndColor(num)
  }

  function getNovaNumber(novaGroup) {
    if (!novaGroup) return null
    
    let num = null
    
    if (typeof novaGroup === 'number') {
      num = novaGroup
    } else if (typeof novaGroup === 'object') {
      if (novaGroup.string) {
        const match = novaGroup.string.match(/\d+/)
        num = match ? parseInt(match[0]) : null
      } else if (typeof novaGroup.value === 'number') {
        num = novaGroup.value
      }
    } else if (typeof novaGroup === 'string') {
      const match = novaGroup.match(/\d+/)
      num = match ? parseInt(match[0]) : null
    }
    
    return num
  }

  function format1(n) {
    const v = Number(n ?? 0)
    return Number.isFinite(v) ? v.toFixed(1) : '0.0'
  }

  async function loadRecipe() {
    if (!authStore.userid) return
    try {
      isLoading.value = true

      // Try to load as a user recipe first
      let r = await getUserRecipeById(authStore.userid, props.id)

      // If not found as user recipe or it's marked as baseRecipe, try loading from base catalog
      if (!r || r.baseRecipe === true) {
        const base = await getBaseRecipeById(props.id)
        if (base) {
          r = base
        } else if (!r) {
          errorMessage.value = 'Recette introuvable.'
          return
        }
      }

      // Récupère tous les barcodes de la recette
      const barcodes = r.ingredients?.map(i => i.id) || []
      const fullInfos = await getIngredientsByBarcodes(authStore.userid, barcodes)

      // Hydrate les ingrédients avec les infos
      const hydratedIngredients = (r.ingredients || []).map(line => {
        const found = fullInfos.find(f => f.id === line.id)
        return {
          ...line,
          name: line.name || found?.productName || line.id,
          productName: found?.productName || line.name || line.id,
          productBrand: found?.productBrand || '',
          novaGroup: line.novaGroup ?? found?.novaGroup ?? null,
          nutritionPer100g: found?.nutritionPer100g || {}
        }
      })

      recipe.value = { id: props.id, ...r, ingredients: hydratedIngredients }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors du chargement de la recette."
    } finally {
      isLoading.value = false
    }
  }

  async function deleteRecipe() {
    if (!canEditBaseRecipe.value) {
      errorMessage.value = "Action réservée aux administrateurs."
      return
    }
    if (!authStore.userid || !recipe.value?.id) return
    try {
      if (recipe.value?.baseRecipe) {
        // delete from base recipes
        await deleteBaseRecipe(recipe.value.id)
      } else {
        await deleteRecipeFromUserCollection(authStore.userid, recipe.value.id)
      }
      askDelete.value = false
      snack.value = { show: true, text: 'Recette supprimée 🗑️' }
      setTimeout(() => router.push('/my_recipes'), 350)
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors de la suppression."
    }
  }

  async function toggleFavorite() {
    if (!authStore.userid || !recipe.value?.id) return
    try {
      const next = !recipe.value.favorite
      await setRecipeAsFavorite(authStore.userid, recipe.value.id, next)
      recipe.value.favorite = next
      snack.value = { show: true, text: next ? 'Ajoutée aux favoris ⭐' : 'Retirée des favoris' }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors de la mise à jour du favori."
    }
  }

  async function createShoppingListFromRecipe() {
    if (!authStore.userid) {
      errorMessage.value = "Utilisateur non connecté."
      return
    }
    const ingredients = recipe.value?.ingredients || []
    if (!ingredients.length) {
      errorMessage.value = "Aucun ingrédient à ajouter."
      return
    }

    const items = ingredients
      .map((ing) => {
        const name = String(ing.name || ing.productName || '').trim()
        if (!name) return null
        const grams = Number(ing.grams)
        const quantity = Number.isFinite(grams) && grams > 0 ? `${grams} g` : 1
        return { name, quantity }
      })
      .filter(Boolean)

    if (!items.length) {
      errorMessage.value = "Aucun ingrédient valide à ajouter."
      return
    }

    const listName = (recipe.value?.title || "Liste de courses").trim()

    try {
      const existingLists = await getUserShoppingLists(authStore.userid)
      const alreadyGenerated = Object.values(existingLists || {}).some((list) => {
        if (!list) return false
        const sameName = String(list.name || "").trim().toLowerCase() === listName.toLowerCase()
        return sameName && list.userGenerated === false
      })
      if (alreadyGenerated) {
        snack.value = { show: true, text: "Cette liste existe déjà." }
        return
      }

      await addShoppingList(authStore.userid, {
        name: listName,
        items,
        userGenerated: false,
      })
      snack.value = { show: true, text: "Liste de courses créée." }
    } catch (e) {
      console.error(e)
      errorMessage.value = "Erreur lors de la création de la liste."
    }
  }

  function editRecipe() {
    if (!canEditBaseRecipe.value) {
      errorMessage.value = "Action réservée aux administrateurs."
      return
    }
    // If this is a base recipe, admins edit via the base recipes editor
    if (recipe.value?.baseRecipe) {
      router.push({ path: '/base_recipes', query: { id: recipe.value.id } })
      return
    }

    // Regular user recipe: open the user recipe editor
    router.push({ path: '/add_recipe', query: { id: recipe.value.id } })
  }

  function requestDelete() {
    if (!canEditBaseRecipe.value) {
      errorMessage.value = "Action réservée aux administrateurs."
      return
    }
    askDelete.value = true
  }

  onMounted(() => {
    // recharge si l’utilisateur change (sécurité) + au 1er montage
    watch(() => authStore.userid, () => loadRecipe(), { immediate: true })
  })

  watch(sourceKey, (v) => {
    validPreview.value = !!v
  })


</script>

