<template>
  <loading-element v-if="isLoadingRecipes" />

  <div class="main bg-primary" v-else>
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        v-if="authStore.userInfos"
        firstElement="Mes"
        secondElement="menus"
        :coloredSecond="true"
      />
      <div class="rowCustom">
        <ThemeToggle />
        <AccountToggle />
      </div>
    </div>

    <div class="recapBanner pa-4 rounded-xl bg-secondary">
      <div class="recapRow">
        <div class="recapCol">
          <h3 class="recapTitle mb-2">Récapitulatif des contraintes de mes menus</h3>

          <p class="recapLine"><strong>Objectif :</strong> {{ $t(weightObjective) }}</p>
          <p class="recapLine">
            <strong>Calories cibles :</strong> {{ targetCalories.toFixed(0) }} kcal
            / jour
          </p>

          <div class="macros recapMacros mt-3">
            <p class="macroItem"><strong>Protéines :</strong> {{ proteinNeeds.toFixed(0) }} g</p>
            <p class="macroItem"><strong>Lipides :</strong> {{ fatNeeds.toFixed(0) }} g</p>
            <p class="macroItem"><strong>Glucides :</strong> {{ carbNeeds.toFixed(0) }} g</p>
          </div>
        </div>

        <div class="recapCol">
          <div class="cookingData">
            <p class="recapLine">
              <strong>Régime alimentaire :</strong>
              {{
                userConstraints.diet.length
                  ? userConstraints.diet.map((d) => $t(d)).join(", ")
                  : "Aucun"
              }}
            </p>
            <p class="recapLine">
              <strong>Intolérances alimentaires :</strong>
              {{
                userConstraints.intolerances.length
                  ? userConstraints.intolerances.map((i) => $t(i)).join(", ")
                  : "Aucune"
              }}
            </p>
            <p class="recapLine">
              <strong>Repas déjà pris dans la journée :</strong>
              {{
                userConstraints.takenMealsObjectives.length
                  ? userConstraints.takenMealsObjectives
                      .map((m) => $t(m))
                      .join(", ")
                  : "Aucun"
              }}
            </p>
          </div>
        </div>
      </div>
    </div>

    <!-- MENU SEMAINE -->
    <div v-if="displayedWeeklyData.daily && displayedWeeklyData.daily.length" class="mt-6">
      <div class="d-flex align-center justify-space-between mb-3">
        <div class="d-flex align-center flex-wrap" style="gap: 10px;">
          <h1 class="mr-3">Menus de la semaine</h1>
          <v-btn
            color="white"
            prepend-icon="mdi-printer"
            elevation="0"
            rounded="lg"
            size="small"
            @click="printMenu"
            :loading="isPrinting"
          >
            Imprimer
          </v-btn>
          <v-btn
            color="secondary"
            prepend-icon="mdi-refresh"
            elevation="0"
            rounded="lg"
            size="small"
            @click="rerollMenu"
          >
            Générer à nouveau
          </v-btn>
          <v-btn
            v-if="showSaveButton"
            color="accent"
            prepend-icon="mdi-content-save"
            elevation="0"
            rounded="lg"
            size="small"
            :loading="isSavingMenu"
            @click="saveMenu"
          >
            {{ saveButtonLabel }}
          </v-btn>
        </div>
        <v-switch v-model="diverse" inset label="Menus diversifiés" />
      </div>

      <v-alert
        v-if="showExpiredNotice"
        type="info"
        variant="tonal"
        class="mb-4"
      >
        Votre menu sauvegardé a plus d'une semaine. Merci de générer et sauvegarder un nouveau menu.
      </v-alert>

      <div class="weekGrid" ref="menuSectionRef">
        <div
          v-for="(day, idx) in displayedWeeklyData.daily"
          :key="idx"
          class="dayCard bg-secondary pa-4 rounded-xl"
        >
          <div class="dayHeader d-flex justify-space-between align-center mb-3">
            <div>
              <h2 class="dayTitle mb-0">Jour {{ idx + 1 }}</h2>
            </div>
            <p class="dayKcal mb-0">{{ day.totals.kcal.toFixed(0) }} kcal</p>
          </div>

          <div v-if="day.menu && Object.keys(day.menu).length">
            <div
              v-for="(meals, mealName) in day.menu"
              :key="mealName"
              class="menuSection mb-3"
            >
              <h4 class="menuTitle mb-1 text-capitalize">{{ $t(mealName) }}</h4>
              <div v-if="meals && meals.length" class="mealList d-flex flex-column">
                <v-card
                  v-for="(recipe, i2) in meals"
                  :key="recipe.id || i2"
                  class="mealCard pa-3"
                  elevation="0"
                >
                  <div class="d-flex justify-space-between align-center">
                    <div>
                      <p class="mealName mb-1">{{ recipe.title || 'Sans titre' }}</p>
                      <div class="mealMeta">
                        <span class="mealCategory">{{ $t(recipe.category) }}</span>
                        <span class="mealKcal">{{ (recipe.totals?.kcal/recipe.servings ?? 0).toFixed(0) }} kcal</span>
                      </div>
                    </div>
                  </div>
                </v-card>
              </div>
              <p v-else class="text-caption text-grey">Aucune recette disponible pour ce repas.</p>
            </div>
          </div>

          <div class="dailyTotals mt-4">
            <p class="dailyTotals__label mb-1">Totaux journaliers</p>
            <p class="dailyTotals__values mb-0">
              P: {{ day.totals.protein.toFixed(0) }}g • 
              L: {{ day.totals.fat.toFixed(0) }}g • 
              G: {{ day.totals.carbs.toFixed(0) }}g
            </p>
          </div>
        </div>
      </div>
    </div>
  </div>

  <v-snackbar
    v-if="errorMessage"
    v-model="errorMessage"
    color="error"
    top
    right
  >
    {{ errorMessage }}
  </v-snackbar>
  <v-snackbar v-model="menuSnack.show" color="success" timeout="2500" top right>
    {{ menuSnack.text }}
  </v-snackbar>
</template>

<script>
import { computed, ref, onMounted, watch } from "vue";
import LoadingElement from "../Animations/LoadingElement.vue";
import TopDeck from "../Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import {
  getBaseMetabolicRate,
  getDailyNeeds,
  getTargetCalories,
  calculateMacros,
} from "@/service/health_service";
import { getUserRecipes } from "@/service/recipe_service";
import { generateMenu, generateWeeklyMenu } from "@/service/menu_service";
import { getUserWeeklyMenu, saveUserWeeklyMenu } from "@/service/menu_storage_service";
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";
import html2canvas from "html2canvas";

export default {
  name: "MenuPage",
  components: { LoadingElement, TopDeck, ThemeToggle, AccountToggle },
  setup() {
    const authStore = useAuthStore();
    const errorMessage = ref("");
    const recipes = ref([]);
    const isLoadingRecipes = ref(false);
    const menuSectionRef = ref(null);
    const isPrinting = ref(false);
    const isSavingMenu = ref(false);
    const menuSnack = ref({ show: false, text: "" });
    const savedMenu = ref(null);
    const savedAt = ref(null);
    const menuSeed = ref(0);
    const useSavedMenu = ref(false);

    const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async () => {
          if (!authStore?.userid) return;
          try {
            isLoadingRecipes.value = true;
            const data = await getUserRecipes(authStore.userid);
            recipes.value = Object.entries(data).map(([id, value]) => ({
              id,
              ...value,
            }));
          } catch (error) {
            errorMessage.value =
              "Erreur lors du chargement des recettes utilisateur.";
            console.error(error);
          } finally {
            isLoadingRecipes.value = false;
          }

          try {
            const saved = await getUserWeeklyMenu(authStore.userid);
            savedMenu.value = saved?.weeklyMenu || null;
            savedAt.value = saved?.savedAt || null;
            const isFresh = saved?.savedAt && Date.now() - saved.savedAt < WEEK_MS;
            useSavedMenu.value = !!saved?.weeklyMenu && isFresh;
          } catch (error) {
            console.error("Erreur chargement menu sauvegardé:", error);
          }
        },
        { immediate: true }
      );
    });

    // Données du store
    const weight = authStore.userInfos?.actualWeight || 70;
    const height = authStore.userInfos?.actualSize || 175;
    const age = authStore.userInfos?.age || 30;
    const sex = authStore.userInfos?.sex || "male";
    const activityLevel = authStore.userInfos?.activityLevel || "sedentary";
    const weightObjective =
      authStore.userInfos?.weightObjective || "maintainWeight";
    const nap = authStore.userInfos?.NAP || 1.5;

    //Cooking data
    const userConstraints = computed(() => ({
      targetCalories: targetCalories.value,
      takenMealsObjectives: authStore.userInfos?.takenMealsObjectives || [
        "breakfast",
        "lunch",
        "dinner",
      ],
      allergies: authStore.userInfos?.allergies || [],
      intolerances: authStore.userInfos?.intolerances || [],
      diet: authStore.userInfos?.diet || [],
      bannedIngredients: authStore.userInfos?.bannedIngredients || [],
      averageCookingTime:
        authStore.userInfos?.averageCookingTime || "15To30Minutes",
      cookingSkills: authStore.userInfos?.cookingSkills || null,
      equipement: authStore.userInfos?.equipement || [],
    }));

    const diverse = ref(true);

    const menuData = computed(() =>
      generateMenu(recipes.value, userConstraints.value)
    );

    const generatedWeeklyData = computed(() => {
      menuSeed.value;
      return generateWeeklyMenu(recipes.value, userConstraints.value, { diverse: diverse.value });
    });

    const hasSavedMenu = computed(() => !!savedMenu.value);
    const isSavedFresh = computed(
      () => !!savedAt.value && Date.now() - savedAt.value < WEEK_MS
    );
    const showExpiredNotice = computed(
      () => hasSavedMenu.value && !isSavedFresh.value
    );
    const displayedWeeklyData = computed(() => {
      if (useSavedMenu.value && hasSavedMenu.value && isSavedFresh.value) {
        return savedMenu.value;
      }
      return generatedWeeklyData.value;
    });

    const showSaveButton = computed(() => !useSavedMenu.value);
    const saveButtonLabel = computed(() =>
      hasSavedMenu.value && isSavedFresh.value ? "Remplacer" : "Sauvegarder"
    );

    // Calculs nutritionnels
    const tmb = computed(() => getBaseMetabolicRate(age, height, weight, sex));
    const dailyNeeds = computed(() => getDailyNeeds(tmb.value, nap));
    const targetCalories = computed(() =>
      getTargetCalories(dailyNeeds.value, weightObjective)
    );

    const macros = computed(() =>
      calculateMacros(
        weight,
        activityLevel,
        weightObjective,
        targetCalories.value
      )
    );

    const proteinNeeds = computed(() => macros.value.proteinNeeds);
    const fatNeeds = computed(() => macros.value.fatNeeds);
    const carbNeeds = computed(() => macros.value.carbNeeds);

    const printMenu = async () => {
      if (!menuSectionRef.value) {
        console.error("Menu section ref non disponible");
        return;
      }

      isPrinting.value = true;

      try {
        const canvas = await html2canvas(menuSectionRef.value, {
          scale: 2,
          useCORS: true,
          backgroundColor: "#ffffff",
          logging: false,
        });

        const imgData = canvas.toDataURL("image/png");
        const printWindow = window.open("", "_blank", "width=900,height=1200");
        
        printWindow.document.write(`
          <html>
            <head>
              <title>Menus de la semaine</title>
              <style>
                body { margin: 0; padding: 0; }
                img { max-width: 100%; height: auto; display: block; }
                @media print {
                  img { page-break-inside: avoid; }
                }
              </style>
            </head>
            <body>
              <img src="${imgData}" />
            </body>
          </html>
        `);

        printWindow.document.close();
        printWindow.onload = () => {
          printWindow.focus();
          printWindow.print();
          printWindow.close();
        };
      } catch (error) {
        console.error("Erreur lors de l'impression:", error);
        errorMessage.value = "Erreur lors de la génération de l'impression";
      } finally {
        isPrinting.value = false;
      }
    };

    const rerollMenu = () => {
      useSavedMenu.value = false;
      menuSeed.value += 1;
    };

    const saveMenu = async () => {
      if (!authStore.userid) {
        errorMessage.value = "Utilisateur non connecté.";
        return;
      }
      const menuToSave = generatedWeeklyData.value;
      if (!menuToSave?.daily?.length) {
        errorMessage.value = "Aucun menu à sauvegarder.";
        return;
      }

      isSavingMenu.value = true;
      try {
        const meta = { diverse: diverse.value };
        const res = await saveUserWeeklyMenu(authStore.userid, menuToSave, meta);
        savedMenu.value = menuToSave;
        savedAt.value = res?.savedAt || Date.now();
        useSavedMenu.value = true;
        menuSnack.value = { show: true, text: "Menu sauvegardé ✅" };
      } catch (error) {
        console.error("Erreur sauvegarde menu:", error);
        errorMessage.value = "Erreur lors de la sauvegarde du menu.";
      } finally {
        isSavingMenu.value = false;
      }
    };

    return {
      //User data
      authStore,
      errorMessage,
      recipes,
      isLoadingRecipes,
      weightObjective,
      targetCalories,
      proteinNeeds,
      fatNeeds,
      carbNeeds,
      //Cooking data,
      userConstraints,
      menuData,
      generatedWeeklyData,
      displayedWeeklyData,
      showSaveButton,
      saveButtonLabel,
      showExpiredNotice,
      diverse,
      //Print
      menuSectionRef,
      isPrinting,
      printMenu,
      rerollMenu,
      saveMenu,
      isSavingMenu,
      menuSnack,
    };
  },
};
</script>

