<template>
  <v-card
    class="pa-4 rounded-xl extension-card"
    elevation="4"
    color="secondary"
    :disabled="item.status === 'not_found'"
  >
    <template v-if="item.status === 'found'">
      <v-row>
        <v-col cols="12" md="12">
          <div class="card-header">
            <div class="ingredientImageContainer">
              <v-img
                :src="item.productImage"
                width="100%"
                height="120"
                class="rounded-lg extension-image"
                contain
              />
            </div>
            <div class="header-meta">
            <div class="nova-chip">
              <v-chip
                v-if="item.novaGroup?.string"
                :color="item.novaGroup.color"
                label
                small
                outlined
              >
                {{ $t(item.novaGroup.string) }}
              </v-chip>
            </div>
            <div class="nutri-score-wrapper">
              <div :class="['nutri-score-pill', nutriScoreClass]">
                <span class="nutri-score-letter">{{ nutriScoreLetter || "—" }}</span>
              </div>
              <span class="nutri-score-label">Nutri-Score</span>
            </div>
            <div class="header-title">{{ localItem.productName || "Nom non disponible" }}</div>
            <div class="header-subtitle">{{ localItem.productBrand || "Marque non disponible" }}</div>
          </div>
          </div>

          <div class="mt-2" v-if="hasUnsafeIntolerances">
