            <div v-if="hasAllergens" class="allergens-banner mt-1">
              <v-icon size="small" class="mr-2">mdi-alert</v-icon>
              <span>{{ safeAllergens.map((a) => $t(a)).join(", ") }}</span>
            </div>
            <div v-else class="mt-1 text-body-2 text-success">
              ✓ Aucun allergène connu
            </div>
          </div>
