<script>
import { useAuthStore } from "@/store/auth_store";
import { checkProductWithIntolerances } from "@/service/intolerance_service";

export default {
  name: "ExtensionResultCard",
  props: {
    item: {
      type: Object,
      required: true
    }
  },
  emits: ['remove', 'update:item'],
  data() {
    return {
      localItem: { ...this.item }
    };
  },
  watch: {
    item: {
      handler(newVal) {
        this.localItem = { ...newVal };
      },
      deep: true
    },
    localItem: {
      handler(newVal) {
        this.$emit('update:item', newVal);
      },
      deep: true
    }
  },
  computed: {
    authStore() {
      return useAuthStore();
    },
    productInfoForIntolerance() {
      const base = this.item?.foodInfo ? { ...this.item.foodInfo } : {};
      const allergens = Array.isArray(this.item?.allergens) ? this.item.allergens : [];
      if (!base.allergens && allergens.length) {
        base.allergens = allergens.join(", ");
      }
      if (!base.allergens_tags && allergens.length) {
        base.allergens_tags = allergens.map((a) =>
          String(a).includes(":") ? String(a) : `en:${a}`
        );
      }
      return Object.keys(base).length ? base : null;
    },
    unsafeIntolerances() {
      const userIntolerances = [
        ...(Array.isArray(this.authStore.userInfos?.intolerances)
          ? this.authStore.userInfos.intolerances
          : []),
        ...(Array.isArray(this.authStore.userInfos?.allergies)
          ? this.authStore.userInfos.allergies
          : []),
      ];
      const productInfo = this.productInfoForIntolerance;
      if (!userIntolerances.length || !productInfo) return [];
      return checkProductWithIntolerances(productInfo, userIntolerances);
    },
    unsafeIntolerancesLabel() {
      return this.unsafeIntolerances.map((i) => `"${this.$t(i)}"`).join(", ");
    },
    unsafeAllergens() {
      const userAllergies = this.authStore.userInfos?.allergies || [];
      const productAllergens = Array.isArray(this.item?.allergens)
        ? this.item.allergens
        : [];
      if (!userAllergies.length || !productAllergens.length) return [];
      const userSet = new Set(userAllergies.map((a) => this.normalizeKey(a)));
      return productAllergens.filter((a) => userSet.has(this.normalizeKey(a)));
    },
    unsafeAllergensLabel() {
      return this.unsafeAllergens.map((a) => `"${this.$t(a)}"`).join(", ");
    },
    safeAllergens() {
      return Array.isArray(this.item?.allergens) ? this.item.allergens : [];
    },
    nutriScoreLetter() {
      const raw = this.item?.nutriscore;
      if (!raw) return "";
      return String(raw).trim().toUpperCase();
    },
    nutriScoreClass() {
      const letter = this.nutriScoreLetter;
      const allowed = ["A", "B", "C", "D", "E"];
      if (allowed.includes(letter)) {
        return `nutri-score-${letter.toLowerCase()}`;
      }
      return "nutri-score-unknown";
    },
    hasAllergens() {
      return this.safeAllergens.length > 0;
    },
    hasUnsafeAllergens() {
      return Array.isArray(this.unsafeAllergens) && this.unsafeAllergens.length > 0;
    },
    hasUnsafeIntolerances() {
      return Array.isArray(this.unsafeIntolerances) && this.unsafeIntolerances.length > 0;
    }
  },
  methods: {
    normalizeKey(value) {
      return String(value)
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .trim();
    }
  }
};
</script>

