<template>
  <div class="rowSpaceBetween fullWidth my-5">
    <TopDeck firstElement="Santé" />
  </div>

  <div class="healthContainer">
    <div class="healthLeft">

      <!-- Répartition des macronutriments -->
      <div class="healthBloc">
        <h3 class="uppercase">Apports journaliers recommandés</h3>
        <p>
          <strong>Calories visées :</strong> {{ targetCalories.toFixed(0) }} kcal / jour
        </p>

        <div class="macros">
          <div class="macro protein">
            <p>Protéines</p>
            <strong>{{ proteinNeeds.toFixed(0) }} g</strong>
          </div>
          <div class="macro fat">
            <p>Lipides</p>
            <strong>{{ fatNeeds.toFixed(0) }} g</strong>
          </div>
          <div class="macro carb">
            <p>Glucides</p>
            <strong>{{ carbNeeds.toFixed(0) }} g</strong>
          </div>
        </div>
      </div>

      <!-- IMC -->
      <div class="healthBloc">
        <h3 class="uppercase">Indice de Masse Corporelle (IMC)</h3>

        <div class="imcBar">
          <div class="zone under"></div>
          <div class="zone normal"></div>
          <div class="zone over"></div>
          <div class="zone obese"></div>
          <div class="zone extreme"></div>
          <div class="indicator" :style="{ left: bmiPercent + '%' }"></div>
        </div>

        <p class="mt-3">
          <strong>Votre IMC :</strong> {{ bmi.toFixed(1) }} – {{ bmiStatus }}
        </p>
      </div>
    </div>

    <div class="healthRight">
      <div class="healthBloc">
        <h3 class="uppercase">Dépenses énergétiques</h3>
        <p><strong>Taux métabolique de base :</strong> {{ tmb.toFixed(0) }} kcal / jour</p>
        <p><strong>Niveau d’activité :</strong> {{ $t(activityLevel) }}</p>
        <p><strong>Besoins journaliers :</strong> {{ dailyNeeds.toFixed(0) }} kcal / jour</p>
        <p><strong>Objectif :</strong> {{ $t(weightObjective) }}</p>
        <p><strong>Ajustement objectif :</strong> {{ calorieAdjustmentLabel }}</p>
        <p v-if="estimatedMonthsLabel"><strong>Temps estimé :</strong> {{ estimatedMonthsLabel }}</p>
        <p><strong>Poids actuel :</strong> {{ formatWeight(actualWeight) }}</p>
        <p><strong>Poids visé :</strong> {{ formatWeight(displayTargetWeight) }}</p>

        <div class="resultCards">
          <div class="card neutral">
            <div class="calorie-line">
              <span class="calDisplay">{{ tmb.toFixed(0) }}</span> 
              <p>kcal</p>
            </div>
            <p>Taux métabolique de base</p>
          </div>
          <div class="card target">
            <div class="calorie-line">
              <span class="calDisplay">{{ targetCalories.toFixed(0) }}</span>
              <p>kcal</p>
            </div>
            <p>Calories visées</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { computed } from "vue";
import TopDeck from "../Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import {
  getBaseMetabolicRate,
  getDailyNeeds,
  getTargetCalories,
  calculateBmiData,
  calculateMacros
} from "@/service/health_service";

export default {
  name: "HealthPage",
  components: { TopDeck },
  setup() {
    const authStore = useAuthStore();

    const toNumber = (value) => {
      const num = Number(value);
      return Number.isFinite(num) ? num : null;
    };

    const actualWeight = computed(() =>
      toNumber(authStore.userInfos?.actualWeight)
    );
    const targetWeight = computed(() =>
      toNumber(authStore.userInfos?.targetWeight)
    );
    const displayTargetWeight = computed(() =>
      targetWeight.value ?? actualWeight.value
    );

    const weight = actualWeight.value ?? 70;
    const height = toNumber(authStore.userInfos?.actualSize) ?? 175;
    const age = authStore.userInfos?.age || 30;
    const sex = authStore.userInfos?.sex || "male";
    const activityLevel = authStore.userInfos?.activityLevel || "sedentary";
    const weightObjective = authStore.userInfos?.weightObjective || "maintainWeight";
    const nap = authStore.userInfos?.NAP || 1.5;

    const bmiData = computed(() => calculateBmiData(height, weight));
    const bmi = computed(() => bmiData.value.bmi);
    const bmiStatus = computed(() => bmiData.value.status);
    const bmiPercent = computed(() => bmiData.value.percent);

    const tmb = computed(() => getBaseMetabolicRate(age, height, weight, sex));
    const dailyNeeds = computed(() => getDailyNeeds(tmb.value, nap));
    const targetCalories = computed(() => getTargetCalories(dailyNeeds.value, weightObjective));

    const macros = computed(() =>
      calculateMacros(weight, activityLevel, weightObjective, targetCalories.value)
    );

    const proteinNeeds = computed(() => macros.value.proteinNeeds);
    const fatNeeds = computed(() => macros.value.fatNeeds);
    const carbNeeds = computed(() => macros.value.carbNeeds);

    const calorieAdjustment = computed(() => {
      if (weightObjective === "gainWeight") return 380;
      if (weightObjective === "loseWeight") return -380;
      return 0;
    });

    const calorieAdjustmentLabel = computed(() => {
      if (calorieAdjustment.value === 0) return "0 kcal (maintien)";
      const sign = calorieAdjustment.value > 0 ? "+" : "";
      return `${sign}${calorieAdjustment.value} kcal (≈ 1,5 kg/mois)`;
    });

    const estimatedMonthsLabel = computed(() => {
      if (weightObjective === "maintainWeight") return "";
      if (actualWeight.value == null || targetWeight.value == null) return "";
      const delta = Math.abs(targetWeight.value - actualWeight.value);
      if (delta === 0) return "Objectif atteint.";
      const months = delta / 1.5;
      return `≈ ${months.toFixed(1).replace(".", ",")} mois`;
    });

    const formatWeight = (value) => {
      if (value == null) return "--";
      return `${value.toFixed(1)} kg`;
    };

    return {
      authStore,
      bmi,
      bmiStatus,
      bmiPercent,
      tmb,
      activityLevel,
      weightObjective,
      dailyNeeds,
      targetCalories,
      proteinNeeds,
      fatNeeds,
      carbNeeds,
      actualWeight,
      displayTargetWeight,
      calorieAdjustmentLabel,
      estimatedMonthsLabel,
      formatWeight,
    };
  },
};
</script>

