<template>
  <AuthLayout>
    <template #form>
      <router-link to="/welcome" class="auth-brand">
        <img src="/assets/logo.png" alt="Logo Saineo" class="auth-brand__mark" />
        <span class="auth-brand__name">saineo</span>
      </router-link>

      <h1 class="auth-title">Créer votre compte</h1>
      <p class="auth-subtitle">
        Dernière étape : renseignez votre email, votre pseudo et choisissez un mot de passe.
      </p>

      <form class="auth-form" @submit.prevent="register">
        <v-text-field
          clearable
          label="Email"
          placeholder="johndoe@gmail.com"
          type="email"
          v-model="email"
          variant="outlined"
          rounded="lg"
          hide-details="auto"
          class="auth-input"
        ></v-text-field>

        <v-text-field
          clearable
          label="Pseudo"
          placeholder="Votre pseudo"
          v-model="username"
          variant="outlined"
          rounded="lg"
          hide-details="auto"
          class="auth-input"
        ></v-text-field>

        <v-text-field
          label="Mot de passe"
          :append-inner-icon="show1 ? 'mdi-eye' : 'mdi-eye-off'"
          :rules="[rules.required, rules.min]"
          :type="show1 ? 'text' : 'password'"
          @click:append="show1 = !show1"
          clearable
          v-model="password"
          variant="outlined"
          rounded="lg"
          hide-details="auto"
          class="auth-input"
        ></v-text-field>

        <v-btn
          rounded="lg"
          size="large"
          type="submit"
          variant="elevated"
          class="auth-btn"
        >
          Créer mon compte
        </v-btn>

        <div class="auth-footer">
          <span>Déjà un compte ?</span>
          <router-link to="/login">Se connecter</router-link>
        </div>
      </form>
    </template>
  </AuthLayout>

  <v-snackbar v-if="errorMessage" v-model="errorMessage" color="error" top right>
    {{ errorMessage }}
  </v-snackbar>
</template>

<script>
import AuthLayout from '@/components/PublicPages/AuthLayout.vue';
import { formStore } from '@/store/register_store';
import { getAuth, createUserWithEmailAndPassword, updateProfile } from "firebase/auth";
import { doc, setDoc } from "firebase/firestore";
import { db } from "@/firebase";

export default {
  name: 'FinalRegister',
  components: { AuthLayout },
  data: () => ({
    email: '',
    username: '',
    password: '',
    responses: formStore.responses,
    errorMessage: '',
    show1: false,
    rules: {
      required: value => !!value || 'Required.',
      min: v => v.length >= 8 || 'Min 8 characters',
    },
  }),
  methods: {
    async register() {
      try {
        const auth = getAuth();
        const cred = await createUserWithEmailAndPassword(auth, this.email, this.password);
        if (cred?.user && this.username) {
          await updateProfile(cred.user, { displayName: this.username });
        }

        const userData = {
          ...this.responses,
          userid: cred.user.uid,
          username: this.username,
          email: this.email,
        };
        await setDoc(doc(db, "User", cred.user.uid), userData);

        this.$router.push('/');
      } catch (error) {
        console.error(error);
        switch (error.code) {
          case 'auth/email-already-in-use':
            this.errorMessage = 'Cet email est déjà utilisé';
            break;
          case 'auth/invalid-email':
            this.errorMessage = 'Email invalide';
            break;
          case 'auth/weak-password':
            this.errorMessage = 'Mot de passe trop faible';
            break;
          default:
            this.errorMessage = 'Une erreur est survenue';
            break;
        }
      }
    },
  },
};
</script>

