  padding: 28px 24px 48px;
}

.headerContainer {
  margin-bottom: 24px;
}

.searchSection {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.importBar {
  flex-wrap: wrap;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 18px;
  border: 1px solid rgba(var(--v-theme-text), 0.1);
  background: rgba(var(--v-theme-secondary), 0.75);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.16);
}

.importBar :deep(.v-btn) {
  text-transform: none;
  letter-spacing: 0.2px;
}

