  font-weight: 600;
  border: 1px solid rgba(var(--v-theme-error), 0.45);
}

.ingredientImageContainer {
  display: flex;
  justify-content: center;
  align-items: center;
}
.opacity-70 {
  opacity: 0.7;
}
</style>
