          </div>
        </div>
      </div>
    </div>

    <div class="bg-secondary pa-8 br-2 full-width dashboardBottom mt-4">
      <div class="dashboardBottomInner">
        <div class="weightProgress bg-primary pa-5 rounded-xl">
          <div class="weightHeader">
            <h3 class="text">Progression du poids</h3>
            <span class="progressBadge">{{ weightProgressLabel }}</span>
          </div>
          <div class="weightRow">
            <div class="weightItem">
              <span class="weightLabel">Poids actuel</span>
              <strong>{{ formatWeight(actualWeight) }}</strong>
            </div>
            <div class="weightItem">
              <span class="weightLabel">Objectif</span>
              <strong>{{ formatWeight(displayTargetWeight) }}</strong>
            </div>
          </div>
          <v-progress-linear
            :model-value="weightProgress"
            height="12"
            rounded
            color="accent"
            class="mt-3 weightProgressBar"
            :class="{ 'weightProgressBar--empty': weightProgress === 0 }"
          />
          <p class="weightInfo mt-3">{{ weightProgressText }}</p>
        </div>

        <div class="healthBlock bg-primary px-6 pb-6 rounded-xl">
          <HealthStatsBloc />
        </div>
