<script>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import { useAuthStore } from "@/store/auth_store";
import { getUserIngredients } from "@/service/ingredient_service";
import { getUserRecipes } from "@/service/recipe_service";
import HealthStatsBloc from "@/components/Account/HealthStatsBloc.vue";

export default {
  name: "HomeBlock",
  components: { HealthStatsBloc },
  setup() {
    const authStore = useAuthStore();
    const router = useRouter();

    const ingredients = ref([]);
    const recipes = ref([]);
    const isLoadingIngredients = ref(false);
    const isLoadingRecipes = ref(false);

    const toNumber = (value) => {
      const num = Number(value);
      return Number.isFinite(num) ? num : null;
    };

    const actualWeight = computed(() =>
      toNumber(authStore.userInfos?.actualWeight)
    );
    const originalWeight = computed(() =>
      toNumber(authStore.userInfos?.originalWeight)
    );
    const targetWeight = computed(() =>
      toNumber(authStore.userInfos?.targetWeight)
    );
    const displayTargetWeight = computed(() =>
      targetWeight.value ?? actualWeight.value
    );

    const weightProgress = computed(() => {
      if (
        actualWeight.value == null ||
        targetWeight.value == null ||
        originalWeight.value == null
      ) {
        return 0;
      }
      const totalDelta = Math.abs(targetWeight.value - originalWeight.value);
      if (totalDelta === 0) return 0;
      const remainingDelta = Math.abs(targetWeight.value - actualWeight.value);
      const progress = Math.round(((totalDelta - remainingDelta) / totalDelta) * 100);
      return Math.min(100, Math.max(0, progress));
    });

    const weightProgressText = computed(() => {
      if (actualWeight.value == null || targetWeight.value == null) {
        return "Renseignez votre poids actuel et votre objectif.";
      }
      if (actualWeight.value === targetWeight.value) {
        return "Objectif atteint. Bravo !";
      }
      const delta = Math.abs(targetWeight.value - actualWeight.value);
      const action =
        actualWeight.value > targetWeight.value ? "perdre" : "prendre";
      const monthlyRate = 1.5;
      const months = delta / monthlyRate;
      const monthsLabel = months.toFixed(1).replace(".", ",");
      return `Il vous reste ${delta.toFixed(1)} kg à ${action} (≈ ${monthsLabel} mois • ${monthlyRate} kg/mois).`;
    });

    const weightProgressLabel = computed(() => {
      if (
        actualWeight.value == null ||
        targetWeight.value == null ||
        originalWeight.value == null
      ) {
        return "0%";
      }
      return weightProgress.value === 0 ? "0%" : `${weightProgress.value}%`;
    });

    const formatWeight = (value) => {
      if (value == null) return "--";
      return `${value.toFixed(1)} kg`;
    };

    const toTimestamp = (raw) => {
      if (!raw) return null;
      if (typeof raw === "number") return raw;
      if (typeof raw === "string") {
        const parsed = Date.parse(raw);
        return Number.isNaN(parsed) ? null : parsed;
      }
      if (typeof raw === "object" && raw.seconds) {
        return raw.seconds * 1000;
      }
      return null;
    };

    const selectLatest = (items, fields) => {
      const enriched = items.map((item, index) => {
        const rawDate = fields
          .map((field) => item?.[field])
          .find((value) => value !== undefined && value !== null);
        return {
          item,
          index,
          ts: toTimestamp(rawDate),
        };
      });

      const sorted = [...enriched].sort((a, b) => {
        if (a.ts && b.ts) return b.ts - a.ts;
        if (a.ts) return -1;
        if (b.ts) return 1;
        return b.index - a.index;
      });

      return sorted.slice(0, 5).map((entry) => entry.item);
    };

    const latestIngredients = computed(() =>
      selectLatest(ingredients.value, [
        "added_dt",
        "addedAt",
        "createdAt",
        "updatedAt",
      ])
    );

    const latestRecipes = computed(() =>
      selectLatest(recipes.value, ["createdAt", "updatedAt"])
    );

    const getRecipeImage = (item) =>
      item?.url || item?.image || item?.imageUrl || "";

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async () => {
          if (!authStore?.userid) return;
          try {
            isLoadingIngredients.value = true;
            const ingredientData = await getUserIngredients(authStore.userid);
            ingredients.value = Object.entries(ingredientData).map(
              ([id, data]) => ({
                id,
                ...data,
              })
            );
          } catch (error) {
            console.error("Erreur récupération ingrédients:", error);
          } finally {
            isLoadingIngredients.value = false;
          }

          try {
            isLoadingRecipes.value = true;
            const recipeData = await getUserRecipes(authStore.userid);
            recipes.value = Object.entries(recipeData).map(([id, data]) => ({
              id,
              ...data,
            }));
          } catch (error) {
            console.error("Erreur récupération recettes:", error);
          } finally {
            isLoadingRecipes.value = false;
          }
        },
        { immediate: true }
      );
    });

    return {
      router,
      isLoadingIngredients,
      isLoadingRecipes,
      latestIngredients,
      latestRecipes,
      getRecipeImage,
      actualWeight,
      targetWeight,
      displayTargetWeight,
      weightProgress,
      weightProgressText,
      weightProgressLabel,
      formatWeight,
    };
  },
};
</script>

