<script setup>
import { defineProps, computed } from "vue";
import { useI18n } from "vue-i18n";
import { useAuthStore } from "@/store/auth_store";
import { checkProductWithIntolerances } from "@/service/intolerance_service";

const props = defineProps({
  product: {
    type: Object,
    required: true,
  },
  alreadyAdded: {
    type: Boolean,
    default: false,
  },
});

const authStore = useAuthStore();
const { t } = useI18n();

const normalizeKey = (value) =>
  String(value)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();

const unsafeIntolerances = computed(() => {
  const userIntolerances = [
    ...(Array.isArray(authStore.userInfos?.intolerances)
      ? authStore.userInfos.intolerances
      : []),
    ...(Array.isArray(authStore.userInfos?.allergies)
      ? authStore.userInfos.allergies
      : []),
  ];
  const productInfo = props.product?.foodInfo;
  if (!userIntolerances.length || !productInfo) return [];
  return checkProductWithIntolerances(productInfo, userIntolerances);
});

const unsafeIntolerancesLabel = computed(() =>
  unsafeIntolerances.value.map((i) => `"${t(i)}"`).join(", ")
);

const unsafeAllergens = computed(() => {
  const userAllergies = authStore.userInfos?.allergies || [];
  const productAllergens = props.product?.allergens || [];
  if (!userAllergies.length || !productAllergens.length) return [];
  const userSet = new Set(userAllergies.map((a) => normalizeKey(a)));
  return productAllergens.filter((a) => userSet.has(normalizeKey(a)));
});

const unsafeAllergensLabel = computed(() =>
  unsafeAllergens.value.map((a) => `"${t(a)}"`).join(", ")
);

const nutriScoreLetter = computed(() => {
  const raw = props.product?.nutriscore;
  if (!raw) return "";
  return String(raw).trim().toUpperCase();
});

const nutriScoreClass = computed(() => {
  const letter = nutriScoreLetter.value;
  const allowed = ["A", "B", "C", "D", "E"];
  if (allowed.includes(letter)) {
    return `nutri-score-${letter.toLowerCase()}`;
  }
  return "nutri-score-unknown";
});
</script>

