<template>
  <AuthLayout>
    <template #form>
      <router-link to="/welcome" class="auth-brand">
        <img src="/assets/logo.png" alt="Logo Saineo" class="auth-brand__mark" />
        <span class="auth-brand__name">saineo</span>
      </router-link>

      <h1 class="auth-title">Bon retour 👋</h1>
      <p class="auth-subtitle">Connectez-vous pour retrouver vos menus personnalisés.</p>

      <form class="auth-form" @submit.prevent="login">
        <v-text-field
          clearable
          label="Email"
          placeholder="johndoe@gmail.com"
          type="email"
          v-model="email"
          variant="outlined"
          rounded="lg"
          hide-details="auto"
          class="auth-input"
        ></v-text-field>

        <v-text-field
          label="Mot de passe"
          :append-inner-icon="show1 ? 'mdi-eye' : 'mdi-eye-off'"
          :rules="[rules.required, rules.min]"
          :type="show1 ? 'text' : 'password'"
          @click:append-inner="show1 = !show1"
          clearable
          v-model="password"
          variant="outlined"
          rounded="lg"
          hide-details="auto"
          class="auth-input"
        ></v-text-field>

        <v-btn
          rounded="lg"
          size="large"
          type="submit"
          variant="elevated"
          class="auth-btn"
        >
          Se connecter
        </v-btn>

        <div class="auth-footer">
          <span>Pas encore de compte ?</span>
          <router-link to="/register">Créer un compte</router-link>
        </div>
      </form>
    </template>
  </AuthLayout>

  <v-snackbar v-if="errorMessage" v-model="errorMessage" color="error" top right>
    {{ errorMessage }}
  </v-snackbar>
</template>
  <script>
  import { getAuth, signInWithEmailAndPassword, GoogleAuthProvider, signInWithPopup } from "firebase/auth";
  import AuthLayout from '@/components/PublicPages/AuthLayout.vue';

    export default {
      components: { AuthLayout },
      data: () => ({
        visible: false,
        email: "",
        password: "",
        errorMessage: "",
        show1: false,
        rules: {
        required: value => !!value || 'Required.',
          min: v => v.length >= 8 || 'Min 8 characters',
        },
      }),
      computed: {
          isValidEmail() {
              const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
              return emailRegex.test(this.forgottenEmail);
          },
      },
      methods: {
        login() {
          signInWithEmailAndPassword(getAuth(), this.email, this.password)
            .then(() => {
                this.$router.push('/');
            })
            .catch((error) => {
              const errorCode = error.code;
              const errorMessage = error.message;
                console.error(errorCode, errorMessage);
                switch (error.code){
                    case 'auth/user-disabled':
                        this.errorMessage = 'Utilisateur désactivé';
                        break;
                    case 'auth/user-not-found':
                        this.errorMessage = 'Utilisateur non trouvé';
                        break;
                    case 'auth/invalid-login-credentials':
                        this.errorMessage = 'Mot de passe ou adresse mail incorrect';
                        break;
                    default:
                        this.errorMessage = 'Une erreur est survenue';
                        break;
                }
            });
        },
        loginWithGoogle() {
          const provider = new GoogleAuthProvider();
            signInWithPopup(getAuth(), provider)
                .then(() => {
                  this.$router.push('/')
                }).catch((error) => {
                    console.error(error);
                });
        }
      }
    }
  </script>

